package analytics

import "sort"

type RouteCount struct { Route string; Count int }

func TopK(routes []string, k int) []RouteCount {
    if k <= 0 { return []RouteCount{} }
    counts := make(map[string]int, len(routes))
    for _, route := range routes { counts[route]++ }
    out := make([]RouteCount, 0, len(counts))
    for route, count := range counts { out = append(out, RouteCount{Route: route, Count: count}) }
    sort.Slice(out, func(i, j int) bool {
        if out[i].Count != out[j].Count { return out[i].Count > out[j].Count }
        return out[i].Route < out[j].Route
    })
    if len(out) > k { out = out[:k] }
    return out
}
